{
  "name": "MFC System - Gestão de Movimento",
  "description": "Sistema completo para gestão de membros (MFCistas), equipes base, permissões e cidades com suporte multi-dispositivo.",
  "requestFramePermissions": [
    "geolocation"
  ]
}

export enum MemberStatus {
  ATIVO = 'Ativo',
  INATIVO = 'Inativo',
  PENDENTE = 'Pendente',
  CONVIDADO = 'Convidado',
  AGUARDANDO = 'Aguardando'
}

export enum UserRoleType {
  ADMIN = 'Administrador',
  COORD_CIDADE = 'Coordenador Cidade',
  COORD_ESTADO = 'Coordenador Estado',
  SEC_COM_CIDADE = 'Secretário Comunicação Cidade',
  SEC_COM_ESTADO = 'Secretário Comunicação Estado',
  COORD_CONDIR = 'Coordenador Condir',
  COORD_EQUIPE_BASE = 'Coordenador Equipe Base',
  VICE_COORD = 'Vice Coordenador',
  TESOUREIRO = 'Tesoureiro',
  USUARIO = 'Usuário'
}

export interface Permission {
  id: string;
  name: string;
  canView: boolean;
  canEdit: boolean;
  canCreate: boolean;
  canDelete: boolean;
  module: 'dashboard' | 'mfcistas' | 'equipes' | 'usuarios' | 'permissoes' | 'cidades';
}

export interface City {
