import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useMemo } from 'react';
import { 
  Users, 
  LayoutDashboard, 
  Layers, 
  UserCog, 
  Settings, 
  MapPin, 
  Menu, 
  X, 
  LogOut,
  ChevronRight,
  UserPlus
} from 'lucide-react';
import Dashboard from './views/Dashboard';
import Members from './views/Members';
import Teams from './views/Teams';
import TeamDetail from './views/TeamDetail';
import MemberProfile from './views/MemberProfile';
import SettingsView from './views/Settings';
import UserManagement from './views/UserManagement';

type View = 'dashboard' | 'mfcistas' | 'equipes' | 'usuarios' | 'permissoes' | 'cidades' | 'perfil-membro' | 'detalhe-equipe';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [selectedMemberId, setSelectedMemberId] = useState<string | null>(null);
  const [selectedTeamId, setSelectedTeamId] = useState<string | null>(null);

  const navigation = [
    { name: 'Dashboard', icon: LayoutDashboard, view: 'dashboard' as View },
    { name: 'MFCistas', icon: Users, view: 'mfcistas' as View },
    { name: 'Equipes Base', icon: Layers, view: 'equipes' as View },
    { name: 'Usuários Sistema', icon: UserCog, view: 'usuarios' as View },
    { name: 'Configurações', icon: Settings, view: 'permissoes' as View },
  ];

  const handleNavigate = (view: View, id?: string) => {
    if (id) {
      if (view === 'perfil-membro') setSelectedMemberId(id);
      if (view === 'detalhe-equipe') setSelectedTeamId(id);
    }
    setCurrentView(view);
    if (window.innerWidth < 1024) setSidebarOpen(false);
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard onNavigate={handleNavigate} />;
      case 'mfcistas':
        return <Members onOpenMember={(id) => handleNavigate('perfil-membro', id)} />;
      case 'equipes':
        return <Teams onOpenTeam={(id) => handleNavigate('detalhe-equipe', id)} />;
      case 'perfil-membro':
        return <MemberProfile memberId={selectedMemberId!} onBack={() => setCurrentView('mfcistas')} />;
      case 'detalhe-equipe':
        return <TeamDetail teamId={selectedTeamId!} onBack={() => setCurrentView('equipes')} onOpenMember={(id) => handleNavigate('perfil-membro', id)} />;
      case 'permissoes':
      case 'cidades':
        return <SettingsView initialTab={currentView === 'cidades' ? 'cidades' : 'permissoes'} />;
      case 'usuarios':
        return <UserManagement />;
      default:
        return <Dashboard onNavigate={handleNavigate} />;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {/* Mobile Backdrop */}
      {sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-20 lg:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-30 w-64 bg-white border-r border-gray-200 transform transition-transform duration-300 ease-in-out
        ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}
        lg:translate-x-0 lg:static lg:block
      `}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-bold">M</div>
              <h1 className="text-xl font-bold text-gray-800">MFC Gestão</h1>
            </div>
            <button className="lg:hidden" onClick={() => setSidebarOpen(false)}>
              <X className="w-6 h-6 text-gray-400" />
            </button>
          </div>

          <nav className="flex-1 px-4 space-y-1">
            {navigation.map((item) => (
              <button
                key={item.name}
                onClick={() => handleNavigate(item.view)}
                className={`
                  w-full flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-colors
                  ${currentView === item.view 
                    ? 'bg-blue-50 text-blue-700' 
                    : 'text-gray-600 hover:bg-gray-100'}
                `}
              >
                <item.icon className={`w-5 h-5 ${currentView === item.view ? 'text-blue-600' : 'text-gray-400'}`} />
                {item.name}
              </button>
            ))}
          </nav>

          <div className="p-4 border-t border-gray-100">
            <div className="flex items-center gap-3 px-2 py-3">
              <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-700 font-semibold">
                AC
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-gray-900 truncate">Alzira Camargo</p>
                <p className="text-xs text-gray-500 truncate">Cidade: Tatuí</p>
              </div>
              <LogOut className="w-5 h-5 text-gray-400 cursor-pointer hover:text-red-500" />
            </div>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-h-0 overflow-hidden">
        {/* Top Navbar */}
        <header className="bg-white border-b border-gray-200 h-16 flex items-center justify-between px-4 lg:px-8">
          <button className="lg:hidden" onClick={() => setSidebarOpen(true)}>
            <Menu className="w-6 h-6 text-gray-600" />
          </button>
          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-2 text-sm text-gray-500">
              <MapPin className="w-4 h-4" />
              <span>Unidade: <strong>Tatuí - SP</strong></span>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button className="p-2 text-gray-400 hover:text-blue-600 transition-colors">
              <UserPlus className="w-6 h-6" />
            </button>
          </div>
        </header>

        {/* Dynamic Content */}
        <main className="flex-1 overflow-y-auto p-4 lg:p-8">
          <div className="max-w-7xl mx-auto">
            {renderContent()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Search, Filter, Plus, MoreVertical, Phone, Mail } from 'lucide-react';
import { mockMembers } from '../mockData';
import { MemberStatus } from '../types';

interface MembersProps {
  onOpenMember: (id: string) => void;
}

const Members: React.FC<MembersProps> = ({ onOpenMember }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('Todos');

  const filteredMembers = mockMembers.filter(m => {
    const matchesSearch = m.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          m.phone.includes(searchTerm);
    const matchesStatus = statusFilter === 'Todos' || m.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  const statuses = ['Todos', ...Object.values(MemberStatus)];

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">MFCistas</h2>
          <p className="text-gray-500">Gerencie todos os membros do movimento.</p>
        </div>
        <button className="bg-blue-600 text-white px-4 py-2 rounded-lg font-medium flex items-center justify-center gap-2 hover:bg-blue-700 transition-colors">
          <Plus className="w-5 h-5" />
          Novo Membro
        </button>
      </div>

      <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm flex flex-col md:flex-row gap-4 items-center">
        <div className="relative flex-1 w-full">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input 
            type="text" 
            placeholder="Buscar por nome ou telefone..."
            className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex items-center gap-2 w-full md:w-auto">
          <Filter className="text-gray-400 w-5 h-5" />
          <select 
            className="flex-1 md:w-48 bg-gray-50 border border-gray-200 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
          >
            {statuses.map(s => (
              <option key={s} value={s}>{s}</option>
            ))}
          </select>
        </div>
      </div>

      <div className="bg-white rounded-xl border border-gray-200 overflow-hidden shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-200">
                <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">Membro</th>
                <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">Contato</th>
                <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">Status</th>
                <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">Equipe Base</th>
                <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wider"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredMembers.map((member) => (
                <tr 
                  key={member.id} 
                  className="hover:bg-gray-50 transition-colors cursor-pointer group"
                  onClick={() => onOpenMember(member.id)}
                >
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-700 font-bold uppercase">
                        {member.name.substring(0, 2)}
                      </div>
                      <div>
                        <p className="text-sm font-semibold text-gray-900">{member.name}</p>
                        <p className="text-xs text-gray-500">{member.profession}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="space-y-1">
                      <div className="flex items-center gap-2 text-xs text-gray-600">
                        <Phone className="w-3 h-3" /> {member.phone}
                      </div>
                      <div className="flex items-center gap-2 text-xs text-gray-600">
                        <Mail className="w-3 h-3" /> {member.id}@mfc.org
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span className={`
                      px-2 py-1 text-xs font-medium rounded-full
                      ${member.status === MemberStatus.ATIVO ? 'bg-green-100 text-green-700' : 
                        member.status === MemberStatus.AGUARDANDO ? 'bg-yellow-100 text-yellow-700' :
                        'bg-gray-100 text-gray-700'}
                    `}>
                      {member.status}
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <p className="text-sm text-gray-600">{member.teamId ? 'São Paulo Apóstolo' : 'Nenhuma'}</p>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right">
                    <button className="text-gray-400 group-hover:text-gray-600">
                      <MoreVertical className="w-5 h-5" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Members;

import React, { useState } from 'react';
import { 
  ArrowLeft, 
  MapPin, 
  Phone, 
  Mail, 
  Calendar, 
  Heart, 
  Briefcase, 
  Award, 
  History,
  ShieldAlert,
  Edit,
  UserCheck
} from 'lucide-react';
import { mockMembers } from '../mockData';

interface MemberProfileProps {
  memberId: string;
  onBack: () => void;
}

const MemberProfile: React.FC<MemberProfileProps> = ({ memberId, onBack }) => {
  const member = mockMembers.find(m => m.id === memberId);
  const [activeTab, setActiveTab] = useState<'pessoal' | 'endereco' | 'saude' | 'historico' | 'acesso'>('pessoal');

  if (!member) return <div>Membro não encontrado</div>;

  const tabs = [
    { id: 'pessoal', label: 'Dados Pessoais', icon: UserCheck },
    { id: 'endereco', label: 'Endereço', icon: MapPin },
    { id: 'saude', label: 'Outros / Saúde', icon: Heart },
    { id: 'historico', label: 'Histórico / Cargos', icon: Award },
    { id: 'acesso', label: 'Dados Acesso', icon: History },
  ];

  return (
    <div className="space-y-6 pb-12">
      <div className="flex items-center gap-4">
        <button onClick={onBack} className="p-2 hover:bg-gray-100 rounded-full transition-colors">
          <ArrowLeft className="w-6 h-6 text-gray-600" />
        </button>
        <h2 className="text-2xl font-bold text-gray-800">Perfil do MFCista</h2>
      </div>

      {/* Header Card */}
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
        <div className="h-32 bg-gradient-to-r from-blue-600 to-indigo-700"></div>
        <div className="px-8 pb-8">
          <div className="flex flex-col md:flex-row md:items-end gap-6 -mt-12">
            <div className="w-24 h-24 md:w-32 md:h-32 rounded-2xl bg-white p-1 shadow-lg">
              <div className="w-full h-full bg-blue-100 rounded-xl flex items-center justify-center text-blue-700 text-3xl font-bold uppercase">
                {member.name.substring(0, 2)}
              </div>
            </div>
            <div className="flex-1 space-y-1">
              <div className="flex flex-col sm:flex-row sm:items-center gap-3">
                <h3 className="text-2xl font-bold text-gray-900">{member.name}</h3>
                <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${member.status === 'Ativo' ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'}`}>
                  {member.status}
                </span>
              </div>
              <div className="flex flex-wrap gap-4 text-sm text-gray-500">
                <div className="flex items-center gap-1.5"><Phone className="w-4 h-4" /> {member.phone}</div>
                <div className="flex items-center gap-1.5"><Calendar className="w-4 h-4" /> MFCista desde {member.mfcDate}</div>
                <div className="flex items-center gap-1.5"><LayersIcon className="w-4 h-4" /> Equipe: São Paulo Apóstolo</div>
              </div>
            </div>
            <div className="flex gap-2">
              <button className="flex-1 sm:flex-none px-4 py-2 bg-blue-600 text-white rounded-lg font-medium hover:bg-blue-700 transition-colors flex items-center justify-center gap-2">
                <Edit className="w-4 h-4" /> Editar
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Main Sections */}
      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* Navigation */}
        <div className="lg:col-span-1 space-y-2">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ${
                activeTab === tab.id 
                ? 'bg-blue-600 text-white shadow-md shadow-blue-200' 
                : 'bg-white text-gray-600 hover:bg-gray-50 border border-gray-100'
              }`}
            >
              <tab.icon className={`w-5 h-5 ${activeTab === tab.id ? 'text-white' : 'text-gray-400'}`} />
              {tab.label}
            </button>
          ))}
        </div>

        {/* Content */}
        <div className="lg:col-span-3">
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-8">
            {activeTab === 'pessoal' && (
              <div className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-6">
                  <InfoItem label="Nome Completo" value={member.name} />
                  <InfoItem label="Nome Crachá" value={member.nickname} />
                  <InfoItem label="Data Nascimento" value={member.dob} />
                  <InfoItem label="Sexo" value={member.gender} />
                  <InfoItem label="RG" value={member.rg} />
                  <InfoItem label="CPF" value={member.cpf} />
                  <InfoItem label="Tipo Sanguíneo" value={member.bloodType} />
                  <InfoItem label="Estado Civil" value={member.maritalStatus} />
                  {member.spouseName && <InfoItem label="Cônjuge" value={member.spouseName} />}
                  {member.marriageDate && <InfoItem label="Data Casamento" value={member.marriageDate} />}
                </div>
              </div>
            )}

            {activeTab === 'endereco' && (
              <div className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-6">
                  <InfoItem label="Logradouro" value={member.street} />
                  <InfoItem label="Número" value={member.number} />
                  <InfoItem label="Bairro" value={member.neighborhood} />
                  <InfoItem label="CEP" value={member.zip} />
                  <InfoItem label="Cidade" value={member.city} />
                  <InfoItem label="Estado" value={member.state} />
                  <InfoItem label="Naturalidade" value={member.naturalness} />
                  <InfoItem label="Condir" value={member.condir} />
                </div>
              </div>
            )}

            {activeTab === 'saude' && (
              <div className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-6">
                  <InfoItem label="Pai" value={member.father} />
                  <InfoItem label="Mãe" value={member.mother} />
                  <InfoItem label="Fuma?" value={member.smoker ? 'Sim' : 'Não'} />
                  <InfoItem label="Dificuldade de Locomoção" value={member.mobilityIssue} />
                  <InfoItem label="Plano de Saúde" value={member.healthPlan} />
                  <InfoItem label="PCD?" value={member.pcd ? 'Sim' : 'Não'} />
                  {member.pcdDescription && <InfoItem label="Descrição Deficiência" value={member.pcdDescription} />}
                  <InfoItem label="Religião" value={member.religion} />
                  <InfoItem label="Profissão" value={member.profession} />
                  <InfoItem label="Escolaridade" value={member.education} />
                </div>
              </div>
            )}

            {activeTab === 'historico' && (
              <div className="space-y-8">
                 <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 flex items-start gap-3">
                  <ShieldAlert className="w-5 h-5 text-blue-600 mt-0.5" />
                  <div>
                    <h4 className="text-sm font-bold text-blue-900">Cargos Atuais no Movimento</h4>
                    <p className="text-sm text-blue-700">Responsabilidades exercidas neste período.</p>
                  </div>
                </div>
                <div className="flex flex-wrap gap-2">
                  {member.movementRoles.map(role => (
                    <span key={role} className="px-3 py-1 bg-white border border-gray-200 text-gray-700 rounded-lg text-sm font-medium">
                      {role}
                    </span>
                  ))}
                  {member.movementRoles.length === 0 && <p className="text-gray-500 italic">Nenhum cargo atribuído. Membro comum.</p>}
                </div>
              </div>
            )}

            {activeTab === 'acesso' && (
              <div className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-6">
                  <InfoItem label="Usuário Sistema" value="alziraloretti" />
                  <InfoItem label="E-mail Acesso" value="farahalziraloretti@gmail.com" />
                  <InfoItem label="Data Cadastro no Sistema" value={member.createdAt} />
                  <InfoItem label="Última Atualização" value={member.updatedAt} />
                </div>
                <div className="flex gap-4">
                  <button className="px-4 py-2 border border-gray-200 rounded-lg text-sm font-medium text-gray-700 hover:bg-gray-50">Redefinir Senha</button>
                  <button className="px-4 py-2 border border-gray-200 rounded-lg text-sm font-medium text-gray-700 hover:bg-gray-50">Alterar E-mail</button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

const InfoItem = ({ label, value }: { label: string; value: string }) => (
  <div className="space-y-1">
    <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider">{label}</p>
    <p className="text-sm font-medium text-gray-900">{value || '---'}</p>
  </div>
);

const LayersIcon = ({ className }: { className: string }) => (
  <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor">
