import React, { useState } from 'react';
import { 
  Users, 
  LayoutDashboard, 
  Layers, 
  UserCog, 
  Settings, 
  MapPin, 
  Menu, 
  X, 
  LogOut,
  ChevronRight,
  UserPlus,
  DollarSign,
  UserCheck
} from 'lucide-react';
import Dashboard from './views/Dashboard';
import Members from './views/Members';
import Teams from './views/Teams';
import TeamDetail from './views/TeamDetail';
import MemberProfile from './views/MemberProfile';
import SettingsView from './views/Settings';
import UserManagement from './views/UserManagement';
import MyTeamView from './views/MyTeam';
import FinanceView from './views/Finance';
import { UserRoleType } from './types';

type View = 'dashboard' | 'mfcistas' | 'equipes' | 'usuarios' | 'permissoes' | 'cidades' | 'perfil-membro' | 'detalhe-equipe' | 'minha-equipe' | 'financeiro';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [selectedMemberId, setSelectedMemberId] = useState<string | null>(null);
  const [selectedTeamId, setSelectedTeamId] = useState<string | null>(null);

  // Simulação de usuário logado (Tesoureira Alzira)
  const currentUser = {
    id: 'u2',
    name: 'Alzira Camargo',
    city: 'Tatuí',
    uf: 'SP',
    role: UserRoleType.TESOUREIRO,
    teamId: 't1'
  };

  const navigation = [
    { name: 'Dashboard', icon: LayoutDashboard, view: 'dashboard' as View },
    { name: 'MFCistas', icon: Users, view: 'mfcistas' as View, roles: [UserRoleType.ADMIN, UserRoleType.COORD_CIDADE, UserRoleType.TESOUREIRO] },
    { name: 'Equipes Base', icon: Layers, view: 'equipes' as View, roles: [UserRoleType.ADMIN, UserRoleType.COORD_CIDADE] },
    { name: 'Minha Equipe', icon: UserCheck, view: 'minha-equipe' as View },
    { name: 'Financeiro', icon: DollarSign, view: 'financeiro' as View, roles: [UserRoleType.ADMIN, UserRoleType.TESOUREIRO, UserRoleType.COORD_CIDADE] },
    { name: 'Usuários Sistema', icon: UserCog, view: 'usuarios' as View, roles: [UserRoleType.ADMIN] },
    { name: 'Configurações', icon: Settings, view: 'permissoes' as View, roles: [UserRoleType.ADMIN] },
  ];

  const filteredNav = navigation.filter(item => !item.roles || item.roles.includes(currentUser.role));

  const handleNavigate = (view: View, id?: string) => {
    if (id) {
      if (view === 'perfil-membro') setSelectedMemberId(id);
      if (view === 'detalhe-equipe') setSelectedTeamId(id);
    }
    setCurrentView(view);
    if (window.innerWidth < 1024) setSidebarOpen(false);
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard onNavigate={handleNavigate} />;
      case 'mfcistas':
        return <Members onOpenMember={(id) => handleNavigate('perfil-membro', id)} />;
      case 'equipes':
        return <Teams onOpenTeam={(id) => handleNavigate('detalhe-equipe', id)} />;
      case 'perfil-membro':
        return <MemberProfile memberId={selectedMemberId!} onBack={() => setCurrentView('mfcistas')} />;
      case 'detalhe-equipe':
        return <TeamDetail teamId={selectedTeamId!} onBack={() => setCurrentView('equipes')} onOpenMember={(id) => handleNavigate('perfil-membro', id)} />;
      case 'minha-equipe':
        return <MyTeamView teamId={currentUser.teamId!} userId={currentUser.id} onOpenMember={(id) => handleNavigate('perfil-membro', id)} />;
      case 'financeiro':
        return <FinanceView cityId="1" />;
      case 'permissoes':
      case 'cidades':
        return <SettingsView initialTab={currentView === 'cidades' ? 'cidades' : 'permissoes'} />;
      case 'usuarios':
        return <UserManagement />;
      default:
        return <Dashboard onNavigate={handleNavigate} />;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {sidebarOpen && (
        <div className="fixed inset-0 bg-black/50 z-20 lg:hidden" onClick={() => setSidebarOpen(false)} />
      )}

      <aside className={`fixed inset-y-0 left-0 z-30 w-64 bg-white border-r border-gray-200 transform transition-transform duration-300 ease-in-out ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 lg:static lg:block`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-bold">M</div>
              <h1 className="text-xl font-bold text-gray-800">MFC Gestão</h1>
            </div>
            <button className="lg:hidden" onClick={() => setSidebarOpen(false)}>
              <X className="w-6 h-6 text-gray-400" />
            </button>
          </div>

          <nav className="flex-1 px-4 space-y-1">
            {filteredNav.map((item) => (
              <button
                key={item.name}
                onClick={() => handleNavigate(item.view)}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-colors ${currentView === item.view ? 'bg-blue-50 text-blue-700' : 'text-gray-600 hover:bg-gray-100'}`}
              >
                <item.icon className={`w-5 h-5 ${currentView === item.view ? 'text-blue-600' : 'text-gray-400'}`} />
                {item.name}
              </button>
            ))}
          </nav>

          <div className="p-4 border-t border-gray-100">
            <div className="flex items-center gap-3 px-2 py-3">
              <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-700 font-semibold">{currentUser.name.substring(0, 2)}</div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-gray-900 truncate">{currentUser.name}</p>
                <p className="text-xs text-gray-500 truncate">{currentUser.role} - {currentUser.city}</p>
              </div>
              <LogOut className="w-5 h-5 text-gray-400 cursor-pointer hover:text-red-500" />
            </div>
          </div>
        </div>
      </aside>

      <div className="flex-1 flex flex-col min-h-0 overflow-hidden">
        <header className="bg-white border-b border-gray-200 h-16 flex items-center justify-between px-4 lg:px-8">
          <button className="lg:hidden" onClick={() => setSidebarOpen(true)}>
            <Menu className="w-6 h-6 text-gray-600" />
          </button>
          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-2 text-sm text-gray-500">
              <MapPin className="w-4 h-4" />
              <span>Unidade: <strong>{currentUser.city} - {currentUser.uf}</strong></span>
              {currentUser.role === UserRoleType.ADMIN && (
                <span className="ml-4 px-2 py-0.5 bg-yellow-100 text-yellow-800 text-xs rounded">Admin Geral</span>
              )}
            </div>
          </div>
        </header>

        <main className="flex-1 overflow-y-auto p-4 lg:p-8">
          <div className="max-w-7xl mx-auto">{renderContent()}</div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Users, DollarSign, History, CheckCircle, Clock, AlertCircle, Plus } from 'lucide-react';
import { mockTeams, mockMembers, mockPayments } from '../mockData';

interface MyTeamViewProps {
  teamId: string;
  userId: string;
  onOpenMember: (id: string) => void;
}

const MyTeamView: React.FC<MyTeamViewProps> = ({ teamId, userId, onOpenMember }) => {
  const [activeTab, setActiveTab] = useState<'membros' | 'mensalidades' | 'historico'>('membros');
  const team = mockTeams.find(t => t.id === teamId);
  const teamMembers = mockMembers.filter(m => m.teamId === teamId);
  const payments = mockPayments.filter(p => p.teamId === teamId);

  if (!team) return <div>Equipe não encontrada.</div>;

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div>
            <h2 className="text-2xl font-bold text-gray-800">{team.name}</h2>
            <p className="text-gray-500">Minha Equipe Base em {team.city}</p>
          </div>
          <div className="flex bg-gray-100 p-1 rounded-xl">
            <button 
              onClick={() => setActiveTab('membros')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${activeTab === 'membros' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-600 hover:text-gray-900'}`}
            >
              Membros
            </button>
            <button 
              onClick={() => setActiveTab('mensalidades')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${activeTab === 'mensalidades' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-600 hover:text-gray-900'}`}
            >
              Mensalidades
            </button>
            <button 
              onClick={() => setActiveTab('historico')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${activeTab === 'historico' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-600 hover:text-gray-900'}`}
            >
              Histórico
            </button>
          </div>
        </div>
      </div>

      {activeTab === 'membros' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {teamMembers.map(member => (
            <div key={member.id} className="bg-white p-5 rounded-xl border border-gray-100 shadow-sm hover:shadow-md transition-shadow cursor-pointer" onClick={() => onOpenMember(member.id)}>
              <div className="flex items-center gap-4 mb-4">
                <div className="w-12 h-12 rounded-full bg-blue-100 text-blue-700 flex items-center justify-center font-bold">
                  {member.name.substring(0, 1)}
                </div>
                <div>
                  <h4 className="font-bold text-gray-900">{member.name}</h4>
                  <p className="text-xs text-gray-500">{member.nickname}</p>
                </div>
              </div>
              <div className="space-y-2 text-sm text-gray-600">
                <p>Status: <span className="text-green-600 font-medium">{member.status}</span></p>
                <p>Aniversário: {member.dob}</p>
                <div className="flex flex-wrap gap-1 pt-2">
                  {member.movementRoles.map(role => (
                    <span key={role} className="px-2 py-0.5 bg-blue-50 text-blue-700 rounded text-[10px] uppercase font-bold">{role}</span>
                  ))}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {activeTab === 'mensalidades' && (
        <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden shadow-sm">
          <div className="p-6 border-b border-gray-100 flex justify-between items-center">
            <h3 className="font-bold text-gray-800">Referência: Outubro / 2023</h3>
            <button className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center gap-2">
              <Plus className="w-4 h-4" /> Novo Lançamento
            </button>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-200">
                  <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase">Membro</th>
                  <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase">Status</th>
                  <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase">Valor</th>
                  <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase">Ação</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {teamMembers.map(member => {
                  const payment = payments.find(p => p.memberId === member.id && p.referenceMonth === '10/2023');
                  return (
                    <tr key={member.id} className="hover:bg-gray-50">
                      <td className="px-6 py-4 text-sm font-medium text-gray-900">{member.name}</td>
                      <td className="px-6 py-4">
                        {payment?.status === 'Pago' ? (
                          <span className="flex items-center gap-1 text-green-600 text-xs font-bold uppercase"><CheckCircle className="w-3 h-3" /> Pago</span>
                        ) : (
                          <span className="flex items-center gap-1 text-yellow-600 text-xs font-bold uppercase"><Clock className="w-3 h-3" /> Pendente</span>
                        )}
                      </td>
                      <td className="px-6 py-4 text-sm text-gray-600">R$ 50,00</td>
                      <td className="px-6 py-4">
                        <button className={`px-3 py-1 rounded text-xs font-bold transition-colors ${payment?.status === 'Pago' ? 'bg-gray-100 text-gray-400 cursor-not-allowed' : 'bg-green-600 text-white hover:bg-green-700'}`}>
                          {payment?.status === 'Pago' ? 'Lançado' : 'Lançar Pago'}
                        </button>
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'historico' && (
        <div className="bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden">
          <div className="p-6 border-b border-gray-100">
             <h3 className="font-bold text-gray-800">Últimos Lançamentos</h3>
          </div>
          <div className="divide-y divide-gray-100">
            {payments.map(p => {
              const member = teamMembers.find(m => m.id === p.memberId);
              return (
                <div key={p.id} className="p-4 flex items-center justify-between hover:bg-gray-50 transition-colors">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-green-50 rounded-lg text-green-600">
                      <DollarSign className="w-5 h-5" />
                    </div>
                    <div>
                      <p className="text-sm font-bold text-gray-900">{member?.name}</p>
                      <p className="text-xs text-gray-500">Mês ref: {p.referenceMonth} | Lançado em {p.date}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-sm font-bold text-green-600">+ R$ {p.amount.toFixed(2)}</p>
                    <p className="text-[10px] text-gray-400">ID: {p.id}</p>
                  </div>
                </div>
              )
            })}
          </div>
        </div>
      )}
    </div>
  );
};

export default MyTeamView;

import React, { useState } from 'react';
import { Shield, MapPin, Plus, Edit, Trash2, CheckCircle, XCircle } from 'lucide-react';
import { mockCities } from '../mockData';
import { UserRoleType, ModuleAction } from '../types';

interface SettingsViewProps {
  initialTab: 'permissoes' | 'cidades';
}

const SettingsView: React.FC<SettingsViewProps> = ({ initialTab }) => {
  const [activeTab, setActiveTab] = useState(initialTab);

  const modules = ['Dashboard', 'MFCistas', 'Equipes', 'Financeiro', 'Usuários', 'Configurações'];
  const actions: ModuleAction[] = ['view', 'create', 'edit', 'delete', 'launch'];

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4 border-b border-gray-200">
        <button 
          onClick={() => setActiveTab('permissoes')}
          className={`pb-4 px-2 text-sm font-medium transition-all relative ${activeTab === 'permissoes' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
        >
          <div className="flex items-center gap-2"><Shield className="w-4 h-4" /> Matriz de Permissões</div>
        </button>
        <button 
          onClick={() => setActiveTab('cidades')}
          className={`pb-4 px-2 text-sm font-medium transition-all relative ${activeTab === 'cidades' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
        >
          <div className="flex items-center gap-2"><MapPin className="w-4 h-4" /> Gestão de Cidades</div>
        </button>
      </div>

      {activeTab === 'permissoes' && (
        <div className="space-y-8">
          <div className="flex justify-between items-center">
            <div>
              <h3 className="text-xl font-bold text-gray-800">Controle de Acesso Granular</h3>
              <p className="text-gray-500 text-sm">Configure o que cada cargo pode realizar no sistema.</p>
            </div>
          </div>

          <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden shadow-sm overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-200">
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase">Módulo / Permissão</th>
                  {Object.values(UserRoleType).slice(0, 5).map(role => (
                    <th key={role} className="px-6 py-4 text-center text-xs font-bold text-gray-500 uppercase">{role}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {modules.map(module => (
                  <React.Fragment key={module}>
                    <tr className="bg-blue-50/50">
                      <td colSpan={6} className="px-6 py-2 text-xs font-bold text-blue-700 uppercase">{module}</td>
                    </tr>
                    {actions.map(action => (
                      <tr key={`${module}-${action}`} className="hover:bg-gray-50 group">
                        <td className="px-10 py-3 text-sm text-gray-600 font-medium capitalize">{action}</td>
                        {Object.values(UserRoleType).slice(0, 5).map(role => (
                          <td key={role} className="px-6 py-3 text-center">
                            <input 
                              type="checkbox" 
                              defaultChecked={role === UserRoleType.ADMIN || (action === 'view')} 
                              className="w-4 h-4 rounded text-blue-600 focus:ring-blue-500 border-gray-300"
                            />
                          </td>
                        ))}
                      </tr>
                    ))}
                  </React.Fragment>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'cidades' && (
        <div className="space-y-6">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="text-lg font-bold text-gray-800">Unidades Federativas</h3>
              <p className="text-sm text-gray-500">Cidades ativas no movimento.</p>
            </div>
            <button className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors flex items-center gap-2">
              <Plus className="w-4 h-4" /> Adicionar Cidade
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {mockCities.map(city => (
              <div key={city.id} className="bg-white p-5 rounded-xl border border-gray-100 shadow-sm flex items-center justify-between group hover:border-blue-200 transition-colors">
                <div>
                  <p className="text-lg font-bold text-gray-900">{city.name}</p>
                  <p className="text-sm text-gray-500">{city.uf}</p>
                </div>
                <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button className="p-2 text-gray-400 hover:text-blue-600"><Edit className="w-4 h-4" /></button>
                  <button className="p-2 text-gray-400 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default SettingsView;

import React, { useState } from 'react';
import { Lock, User, Eye, EyeOff, LogIn, AlertCircle } from 'lucide-react';
import { mockUsers } from '../mockData';
import { User as UserType } from '../types';

interface LoginProps {
  onLogin: (user: UserType) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    // Simulação de delay de rede
    setTimeout(() => {
      const user = mockUsers.find(u => u.username === username.toLowerCase());

      // No mock, qualquer senha serve, ou validamos algo simples
      if (user) {
        onLogin(user);
      } else {
        setError('Usuário não encontrado ou senha incorreta.');
      }
      setLoading(false);
    }, 800);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <div className="max-w-md w-full">
        <div className="text-center mb-10">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-blue-600 rounded-3xl shadow-xl shadow-blue-200 mb-6 transform hover:rotate-12 transition-transform">
            <span className="text-white text-4xl font-bold">M</span>
          </div>
          <h1 className="text-3xl font-bold text-gray-900 tracking-tight">MFC Gestão</h1>
          <p className="text-gray-500 mt-2 font-medium">Movimento Familiar Cristão</p>
        </div>

        <div className="bg-white rounded-3xl shadow-2xl shadow-blue-100/50 p-8 border border-gray-100">
          <h2 className="text-xl font-bold text-gray-800 mb-8">Acesse sua conta</h2>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Usuário</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                  <User className="h-5 w-5 text-gray-400" />
                </div>
                <input
                  type="text"
                  required
                  className="block w-full pl-11 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-2xl text-gray-900 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all"
                  placeholder="Seu usuário (ex: admin)"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Senha</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                  <Lock className="h-5 w-5 text-gray-400" />
                </div>
                <input
                  type={showPassword ? 'text' : 'password'}
                  required
                  className="block w-full pl-11 pr-12 py-3 bg-gray-50 border border-gray-200 rounded-2xl text-gray-900 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all"
                  placeholder="••••••••"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
                <button
                  type="button"
                  className="absolute inset-y-0 right-0 pr-4 flex items-center text-gray-400 hover:text-blue-600"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                </button>
              </div>
            </div>

            {error && (
              <div className="bg-red-50 border border-red-100 rounded-xl p-4 flex items-start gap-3 text-red-700 text-sm animate-shake">
                <AlertCircle className="h-5 w-5 shrink-0" />
                <span>{error}</span>
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full flex items-center justify-center gap-2 py-4 bg-blue-600 hover:bg-blue-700 disabled:bg-blue-300 text-white font-bold rounded-2xl shadow-lg shadow-blue-200 transition-all active:scale-[0.98]"
            >
              {loading ? (
                <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin" />
              ) : (
                <>
                  <LogIn className="h-5 w-5" />
                  Entrar no Sistema
                </>
              )}
            </button>
          </form>

          <div className="mt-8 text-center">
            <a href="#" className="text-sm font-medium text-blue-600 hover:underline">Esqueceu sua senha?</a>
          </div>
        </div>

        <p className="mt-10 text-center text-sm text-gray-400">
          Dica: Use <strong>admin</strong> ou <strong>alziraloretti</strong> para testar.
        </p>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { 
  Users, 
  LayoutDashboard, 
  Layers, 
  UserCog, 
  Settings, 
  MapPin, 
  Menu, 
  X, 
  LogOut,
  ChevronRight,
  UserPlus,
  DollarSign,
  UserCheck,
  ChevronDown
} from 'lucide-react';
import Dashboard from './views/Dashboard';
import Members from './views/Members';
import Teams from './views/Teams';
import TeamDetail from './views/TeamDetail';
import MemberProfile from './views/MemberProfile';
import SettingsView from './views/Settings';
import UserManagement from './views/UserManagement';
import MyTeamView from './views/MyTeam';
import FinanceView from './views/Finance';
import Login from './views/Login';
import { UserRoleType, User as UserType } from './types';
import { mockCities } from './mockData';

type View = 'dashboard' | 'mfcistas' | 'equipes' | 'usuarios' | 'permissoes' | 'cidades' | 'perfil-membro' | 'detalhe-equipe' | 'minha-equipe' | 'financeiro';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<UserType | null>(null);
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [selectedMemberId, setSelectedMemberId] = useState<string | null>(null);
  const [selectedTeamId, setSelectedTeamId] = useState<string | null>(null);
  const [selectedCityId, setSelectedCityId] = useState<string>('1');

  // Recuperar cidade do usuário logado
  useEffect(() => {
    if (currentUser) {
      setSelectedCityId(currentUser.cityId);
    }
  }, [currentUser]);

  if (!currentUser) {
    return <Login onLogin={(user) => setCurrentUser(user)} />;
  }

  const currentCity = mockCities.find(c => c.id === selectedCityId) || mockCities[0];

  const navigation = [
    { name: 'Dashboard', icon: LayoutDashboard, view: 'dashboard' as View },
    { name: 'MFCistas', icon: Users, view: 'mfcistas' as View, roles: [UserRoleType.ADMIN, UserRoleType.COORD_CIDADE, UserRoleType.TESOUREIRO, UserRoleType.COORD_ESTADO] },
    { name: 'Equipes Base', icon: Layers, view: 'equipes' as View, roles: [UserRoleType.ADMIN, UserRoleType.COORD_CIDADE] },
    { name: 'Minha Equipe', icon: UserCheck, view: 'minha-equipe' as View, roles: [UserRoleType.TESOUREIRO, UserRoleType.COORD_EQUIPE_BASE, UserRoleType.USUARIO] },
    { name: 'Financeiro', icon: DollarSign, view: 'financeiro' as View, roles: [UserRoleType.ADMIN, UserRoleType.TESOUREIRO, UserRoleType.COORD_CIDADE, UserRoleType.COORD_ESTADO] },
    { name: 'Usuários Sistema', icon: UserCog, view: 'usuarios' as View, roles: [UserRoleType.ADMIN] },
    { name: 'Configurações', icon: Settings, view: 'permissoes' as View, roles: [UserRoleType.ADMIN] },
  ];

  const filteredNav = navigation.filter(item => !item.roles || item.roles.includes(currentUser.role));

  const handleNavigate = (view: View, id?: string) => {
    if (id) {
      if (view === 'perfil-membro') setSelectedMemberId(id);
      if (view === 'detalhe-equipe') setSelectedTeamId(id);
    }
    setCurrentView(view);
    if (window.innerWidth < 1024) setSidebarOpen(false);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentView('dashboard');
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard onNavigate={handleNavigate} />;
      case 'mfcistas':
        return <Members onOpenMember={(id) => handleNavigate('perfil-membro', id)} />;
      case 'equipes':
        return <Teams onOpenTeam={(id) => handleNavigate('detalhe-equipe', id)} />;
      case 'perfil-membro':
        return <MemberProfile memberId={selectedMemberId!} onBack={() => setCurrentView('mfcistas')} />;
      case 'detalhe-equipe':
        return <TeamDetail teamId={selectedTeamId!} onBack={() => setCurrentView('equipes')} onOpenMember={(id) => handleNavigate('perfil-membro', id)} />;
      case 'minha-equipe':
        return <MyTeamView teamId={currentUser.teamId || 't1'} userId={currentUser.id} onOpenMember={(id) => handleNavigate('perfil-membro', id)} />;
      case 'financeiro':
        return <FinanceView cityId={selectedCityId} />;
      case 'permissoes':
      case 'cidades':
        return <SettingsView initialTab={currentView === 'cidades' ? 'cidades' : 'permissoes'} />;
      case 'usuarios':
        return <UserManagement />;
      default:
        return <Dashboard onNavigate={handleNavigate} />;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {sidebarOpen && (
        <div className="fixed inset-0 bg-black/50 z-20 lg:hidden" onClick={() => setSidebarOpen(false)} />
      )}

      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-30 w-64 bg-white border-r border-gray-200 transform transition-transform duration-300 ease-in-out ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 lg:static lg:block`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-bold">M</div>
              <h1 className="text-xl font-bold text-gray-800">MFC Gestão</h1>
            </div>
            <button className="lg:hidden" onClick={() => setSidebarOpen(false)}>
              <X className="w-6 h-6 text-gray-400" />
            </button>
          </div>

          <nav className="flex-1 px-4 space-y-1">
            {filteredNav.map((item) => (
              <button
                key={item.name}
                onClick={() => handleNavigate(item.view)}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ${currentView === item.view ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' : 'text-gray-600 hover:bg-gray-50'}`}
              >
                <item.icon className={`w-5 h-5 ${currentView === item.view ? 'text-white' : 'text-gray-400'}`} />
                {item.name}
              </button>
            ))}
          </nav>

          <div className="p-4 border-t border-gray-100">
            <div className="bg-gray-50 rounded-2xl p-3">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-700 font-bold">
                  {currentUser.name.substring(0, 2)}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-bold text-gray-900 truncate">{currentUser.name}</p>
                  <p className="text-[10px] text-gray-500 uppercase font-bold tracking-wider truncate">{currentUser.role}</p>
                </div>
                <button onClick={handleLogout} className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors">
                  <LogOut className="w-5 h-5" />
                </button>
              </div>
            </div>
          </div>
        </div>
      </aside>

