const GeneralLedger: React.FC = () => {
  const [entities, setEntities] = useState<FinancialEntity[]>([
    { id: '1', name: 'Livraria', year: 2024, createdBy: 'Admin', initialBalance: 1500 }
  ]);
  const [selectedEntityId, setSelectedEntityId] = useState<string>('1');
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [showEntityModal, setShowEntityModal] = useState(false);
  const [showLaunchModal, setShowLaunchModal] = useState(false);
  const [notification, setNotification] = useState<string | null>(null);

  // Estados do formulário de entidade
  const [newEntity, setNewEntity] = useState({ name: '', year: 2024, observations: '', initialBalance: 0 });

  // Estados do formulário de lançamento
  const [launchForm, setLaunchForm] = useState({
    type: 'Receita' as 'Receita' | 'Despesa',
    category: '',
    amount: '',
    description: '',
    months: [] as number[]
  });

  const monthNames = [
    'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
    'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'
  ];

  const categories = {
    Receita: ['Vendas - Dinheiro', 'Vendas - PIX', 'Vendas - Cartão', 'Doações', 'Outros'],
    Despesa: ['Compra de Estoque', 'Material de Escritório', 'Manutenção', 'Frete', 'Impostos', 'Outros']
  };

  const notify = (msg: string) => {
    setNotification(msg);
    setTimeout(() => setNotification(null), 3000);
  };

  const handleCreateEntity = () => {
    const entity: FinancialEntity = {
      id: Math.random().toString(36).substr(2, 9),
      name: newEntity.name,
      year: newEntity.year,
      createdBy: 'Admin',
      observations: newEntity.observations,
      initialBalance: Number(newEntity.initialBalance)
    };
    setEntities([...entities, entity]);
    setSelectedEntityId(entity.id);
    setShowEntityModal(false);
    setNewEntity({ name: '', year: 2024, observations: '', initialBalance: 0 });
    notify('Entidade criada com sucesso!');
  };

  const handleLaunch = () => {
    const newTransactions: Transaction[] = [];
    const baseId = Math.random().toString(36).substr(2, 5);

    // Se nenhum mês selecionado, não faz nada
    if (launchForm.months.length === 0) return;

    const t: Transaction = {
      id: baseId,
      entityId: selectedEntityId,
      type: launchForm.type,
      category: launchForm.category,
      amount: Number(launchForm.amount),
      description: launchForm.description,
      months: [...launchForm.months],
      year: 2024,
      date: new Date().toISOString()
    };

    setTransactions([...transactions, t]);
    setShowLaunchModal(false);
    setLaunchForm({ type: 'Receita', category: '', amount: '', description: '', months: [] });
    notify('Lançamento(s) realizado(s) com sucesso!');
  };

  const toggleMonthSelection = (idx: number) => {
    setLaunchForm(prev => ({
      ...prev,
      months: prev.months.includes(idx) 
        ? prev.months.filter(m => m !== idx) 
        : [...prev.months, idx]
    }));
  };

  const getMonthStats = (monthIdx: number) => {
    const monthTransactions = transactions.filter(t => 
      t.entityId === selectedEntityId && t.months.includes(monthIdx)
    );

    const receita = monthTransactions
      .filter(t => t.type === 'Receita')
      .reduce((acc, curr) => acc + curr.amount, 0);

    const despesa = monthTransactions
      .filter(t => t.type === 'Despesa')
      .reduce((acc, curr) => acc + curr.amount, 0);

    return { receita, despesa, saldo: receita - despesa };
  };

  const selectedEntity = entities.find(e => e.id === selectedEntityId);

  return (
    <div className="space-y-8 pb-10">
      {/* Notificação Toast */}
      {notification && (
        <div className="fixed top-20 right-8 z-[100] bg-green-600 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in fade-in slide-in-from-right duration-300">
          <Check className="w-5 h-5" />
          <span className="font-bold">{notification}</span>
        </div>
      )}

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h2 className="text-3xl font-bold text-gray-900 flex items-center gap-3">
            <BookOpen className="w-8 h-8 text-blue-600" /> Livro Caixa
          </h2>
          <p className="text-gray-500 font-medium">Gestão de entradas e saídas por entidade/evento.</p>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={() => setShowEntityModal(true)}
            className="bg-white border border-gray-200 text-gray-700 px-5 py-2.5 rounded-2xl font-bold hover:bg-gray-50 transition-all flex items-center gap-2"
          >
            <Plus className="w-5 h-5 text-blue-600" /> Nova Entidade
          </button>
          <button 
            onClick={() => setShowLaunchModal(true)}
            className="bg-blue-600 text-white px-6 py-2.5 rounded-2xl font-bold shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all flex items-center gap-2"
