        </header>

        {/* Content Section Rolável */}
        <main className="flex-1 overflow-y-auto p-6 lg:p-10 no-scrollbar bg-[#F8FAFC]">
          <div className="max-w-7xl mx-auto pb-20">
            {renderContent()}
          </div>
        </main>
      </div>
    </div>
  );
};

