  teamId?: string;
  createdAt: string;
  updatedAt: string;
}

export interface Payment {
  id: string;
  memberId: string;
  teamId: string;
  amount: number;
  date: string;
  referenceMonth: string;
  status: 'Pago' | 'Pendente' | 'Isento';
  launchedBy: string;
}

export interface FinancialEntity {
  id: string;
  name: string;
  year: number;
  createdBy: string;
  observations?: string;
  initialBalance: number;
}

export interface Transaction {
  id: string;
  entityId: string;
  type: 'Receita' | 'Despesa';
  category: string;
  amount: number;
  description: string;
  months: number[]; // 0-11 representing Jan-Dec
  year: number;
  date: string;
