export interface Member {
  id: string;
  name: string;
  nickname: string;
  dob: string;
  rg: string;
  cpf: string;
  bloodType: string;
  gender: string;
  maritalStatus: string;
  spouseName?: string;
  spouseCpf?: string;
  marriageDate?: string;
  mfcDate: string;
  phone: string;
  emergencyPhone: string;
  status: MemberStatus;
  teamId?: string;
  street: string;
  number: string;
  neighborhood: string;
  zip: string;
  complement?: string;
  city: string;
  state: string;
