                <div className="p-8 space-y-6 flex-1 overflow-y-auto no-scrollbar">
                    <div className="space-y-4">
                        <div>
                            <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">EVENTO ATIVO</label>
