                                    <p className="text-base font-black text-gray-900">
                                        R$ {localPayments.filter(p => group.members.some(m => m.id === p.memberId) && p.referenceMonth.includes(`/${viewYear}`)).reduce((acc, p) => acc + p.amount, 0).toFixed(2)}
                                    </p>
                                </div>
                                <button 
                                    onClick={() => {
                                        setPaymentForm({ ...paymentForm, month: viewMonth, year: viewYear, observation: '' });
                                        setSelectedForPayment({ memberIds: group.members.map(m => m.id), displayName: group.displayName });
                                        setShowPayModal(true);
                                    }}
                                    className={`px-8 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all flex items-center gap-2 shadow-xl active:scale-95 ${isPaidThisMonth ? 'bg-emerald-100 text-emerald-700 shadow-emerald-50' : 'bg-blue-600 text-white hover:bg-blue-700 shadow-blue-100'}`}
                                >
                                    {isPaidThisMonth ? <CheckCircle2 className="w-4 h-4" /> : <Plus className="w-4 h-4" />}
                                    {isPaidThisMonth ? 'Recebido' : 'Lançar Pagamento'}
                                </button>
                            </div>
                        </div>
                    );
                })}
            </div>
          </div>
        </div>
      )}

      {/* MODAL LANÇAR PAGAMENTO - ZÉ, AQUI VOCÊ COLOCA A OBSERVAÇÃO */}
      {showPayModal && selectedForPayment && (
          <div className="fixed inset-0 z-[500] flex items-center justify-center p-6 bg-slate-900/70 backdrop-blur-md animate-in fade-in duration-300">
            <div className="bg-white w-full max-w-lg rounded-[3rem] shadow-2xl flex flex-col overflow-hidden border border-gray-100 animate-in zoom-in-95 duration-500">
                <div className="p-10 border-b border-gray-50 bg-white text-center flex flex-col items-center gap-4">
