                    <div className="space-y-2">
                        <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Ano Exercício</label>
                        <select 
                            className="w-full bg-gray-50 border border-gray-100 rounded-xl px-4 py-3 text-xs font-black text-gray-700 outline-none"
