                    );
                })}
            </div>
          </div>
        </div>
      )}

      {/* MODAL LANÇAR PAGAMENTO */}
      {showPayModal && selectedForPayment && (
          <div className="fixed inset-0 z-[500] flex items-center justify-center p-6 bg-slate-900/70 backdrop-blur-md animate-in fade-in duration-300">
            <div className="bg-white w-full max-w-lg rounded-[3rem] shadow-2xl flex flex-col overflow-hidden border border-gray-100 animate-in zoom-in-95 duration-500">
                <div className="p-10 border-b border-gray-50 bg-white text-center flex flex-col items-center gap-4">
