                    <div>
                        <h3 className="text-2xl font-black text-gray-900 tracking-tight leading-none">Confirmar Recebimento</h3>
                        <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-2">LANÇAMENTO DE MENSALIDADE</p>
                    </div>
                </div>

                <div className="p-10 space-y-8 overflow-y-auto max-h-[60vh] no-scrollbar">
                    <div className="bg-gray-50 p-6 rounded-2xl border border-gray-100">
                        <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Membro/Casal</p>
                        <p className="text-lg font-black text-gray-800">{selectedForPayment.displayName}</p>
                    </div>

                    <div className="grid grid-cols-2 gap-6">
                        <div className="space-y-2">
                            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Mês de Referência</label>
                            <select 
                                className="w-full bg-gray-50 border border-gray-100 rounded-xl px-5 py-3.5 text-sm font-black text-gray-700 outline-none"
                                value={paymentForm.month}
                                onChange={(e) => setPaymentForm({...paymentForm, month: parseInt(e.target.value)})}
                            >
                                {monthNames.map((n, i) => <option key={i} value={i+1}>{n}</option>)}
                            </select>
                        </div>
                        <div className="space-y-2">
                            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Ano de Referência</label>
                            <select 
                                className="w-full bg-gray-50 border border-gray-100 rounded-xl px-5 py-3.5 text-sm font-black text-gray-700 outline-none"
                                value={paymentForm.year}
                                onChange={(e) => setPaymentForm({...paymentForm, year: parseInt(e.target.value)})}
                            >
                                <option value={2026}>2026</option>
                                <option value={2025}>2025</option>
                                <option value={2024}>2024</option>
                            </select>
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Valor Unitário (R$)</label>
                        <input 
                            type="number" 
                            className="w-full bg-gray-50 border border-gray-100 rounded-xl px-5 py-4 text-lg font-black text-emerald-700 outline-none focus:ring-4 focus:ring-emerald-50"
                            value={paymentForm.amount}
                            onChange={(e) => setPaymentForm({...paymentForm, amount: parseFloat(e.target.value)})}
                        />
                    </div>

                    <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Observações (Opcional)</label>
                        <textarea 
                            rows={3}
                            placeholder="Ex: Pago via PIX pelo João, Pagamento adiantado..."
                            className="w-full bg-gray-50 border border-gray-100 rounded-xl px-5 py-4 text-sm font-bold text-gray-600 outline-none focus:ring-4 focus:ring-blue-50 resize-none"
                            value={paymentForm.observation}
                            onChange={(e) => setPaymentForm({...paymentForm, observation: e.target.value})}
                        />
                    </div>
                </div>

                <div className="p-10 bg-gray-50 border-t border-gray-100 flex flex-col gap-4">
                    <button 
                        onClick={handleLaunchPayment}
                        className="w-full bg-emerald-600 text-white py-5 rounded-[1.5rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl shadow-emerald-100 hover:bg-emerald-700 transition-all active:scale-95 flex items-center justify-center gap-3"
                    >
                        <Save className="w-5 h-5" /> Confirmar e Salvar
                    </button>
                    <button 
                        onClick={() => setShowPayModal(false)}
                        className="text-[10px] font-black text-gray-400 uppercase tracking-widest hover:text-red-500 transition-colors"
                    >
                        CANCELAR OPERAÇÃO
                    </button>
                </div>
            </div>
          </div>
      )}

      {/* Outras abas (Membros, Eventos) permanecem aqui... */}
      {activeTab === 'membros' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in fade-in duration-500">
          {membersState.map(member => (
            <div key={member.id} className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm hover:shadow-2xl transition-all cursor-pointer group" onClick={() => onOpenMember(member.id)}>
              <div className="flex items-center gap-4 mb-6">
                <div className="w-14 h-14 rounded-2xl bg-blue-50 text-blue-600 flex items-center justify-center font-black text-xl group-hover:bg-blue-600 group-hover:text-white transition-all">
                  {member.name.substring(0, 1)}
