export default MyTeamView;

import React, { useState, useMemo } from 'react';
import { 
  Users, 
  DollarSign, 
  History, 
  Clock, 
  AlertCircle, 
  Plus, 
  X, 
  Calendar,
  Save,
  CheckCircle2,
  TrendingUp,
  AlertTriangle,
  MapPin,
  Heart,
  BarChart3,
  Search,
  ChevronDown,
  Info
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell 
} from 'recharts';
import { mockTeams, mockMembers, mockPayments } from '../mockData';
import { Payment, Member } from '../types';

interface MyTeamViewProps {
  teamId: string;
  userId: string;
  onOpenMember: (id: string) => void;
}

const MyTeamView: React.FC<MyTeamViewProps> = ({ teamId, userId, onOpenMember }) => {
  const [activeTab, setActiveTab] = useState<'membros' | 'mensalidades'>('membros');
  const [showPayModal, setShowPayModal] = useState(false);

  // Configuração de Visualização (Zé, inicia sempre em 2026 como você pediu)
  const [viewYear, setViewYear] = useState(2026);
  const [viewMonth, setViewMonth] = useState(new Date().getMonth() + 1);

  const [selectedForPayment, setSelectedForPayment] = useState<{memberIds: string[], displayName: string} | null>(null);
  const [paymentForm, setPaymentForm] = useState({
    month: new Date().getMonth() + 1,
    year: 2026,
    amount: 50.00,
    observation: ''
  });

  const [membersState] = useState<Member[]>(mockMembers.filter(m => m.teamId === teamId));
  const team = mockTeams.find(t => t.id === teamId);
  const [localPayments, setLocalPayments] = useState<Payment[]>(mockPayments.filter(p => p.teamId === teamId));

  const monthNames = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"];
  const shortMonths = ["Jan", "Fev", "Mar", "Abr", "Mai", "Jun", "Jul", "Ago", "Set", "Out", "Nov", "Dez"];

  // Cálculos Financeiros Dinâmicos
  const financeStats = useMemo(() => {
    const currentRef = `${viewMonth}/${viewYear}`;

    const monthlyTotal = localPayments
      .filter(p => p.referenceMonth === currentRef && p.status === 'Pago')
      .reduce((acc, p) => acc + p.amount, 0);

    const yearlyTotal = localPayments
      .filter(p => p.referenceMonth.endsWith(`/${viewYear}`) && p.status === 'Pago')
      .reduce((acc, p) => acc + p.amount, 0);

    // Cálculo de Pendência Real: Todos os meses que faltam pagar até o mês atual selecionado
    let pendingAmount = 0;
    membersState.forEach(m => {
       for(let mIdx = 1; mIdx <= viewMonth; mIdx++) {
          const ref = `${mIdx}/${viewYear}`;
          const isPaid = localPayments.some(p => p.memberId === m.id && p.referenceMonth === ref);
          if(!isPaid) pendingAmount += 50.00; // Valor padrão da mensalidade
       }
    });

    return { monthlyTotal, yearlyTotal, pendingAmount };
  }, [localPayments, viewMonth, viewYear, membersState]);

  // Dados para o Gráfico Anual
  const chartData = useMemo(() => {
    return shortMonths.map((name, index) => {
      const monthNum = index + 1;
      const total = localPayments
        .filter(p => p.referenceMonth === `${monthNum}/${viewYear}` && p.status === 'Pago')
        .reduce((acc, p) => acc + p.amount, 0);
      return { name, total };
    });
  }, [localPayments, viewYear]);

  // Agrupamento Inteligente (Casal/Solteiro) e Detalhamento de Atrasos
  const groupedMembers = useMemo(() => {
    const processed = new Set<string>();
    const groups: any[] = [];

    membersState.forEach(member => {
      if (processed.has(member.id)) return;

      const spouse = membersState.find(m => 
        m.id !== member.id && 
        (m.name === member.spouseName || m.spouseName === member.name)
      );

      const getPendingMonths = (mId: string) => {
        const pending = [];
        // Olha do mês 1 até o mês atual da visão
        for(let mIdx = 1; mIdx <= viewMonth; mIdx++) {
          const ref = `${mIdx}/${viewYear}`;
          if (!localPayments.some(p => p.memberId === mId && p.referenceMonth === ref)) {
            pending.push(shortMonths[mIdx-1]);
          }
        }
        return pending;
      };

      if (spouse) {
        const p1 = getPendingMonths(member.id);
        const p2 = getPendingMonths(spouse.id);
        // União dos meses pendentes do casal
        const allPending = Array.from(new Set([...p1, ...p2]));

        groups.push({ 
          type: 'couple', 
          members: [member, spouse], 
          displayName: `${member.nickname || member.name.split(' ')[0]} & ${spouse.nickname || spouse.name.split(' ')[0]}`, 
          pendingMonths: allPending
        });
        processed.add(member.id);
        processed.add(spouse.id);
      } else {
        groups.push({ 
          type: 'single', 
          members: [member], 
          displayName: member.name, 
          pendingMonths: getPendingMonths(member.id)
        });
        processed.add(member.id);
      }
    });

    return groups.sort((a, b) => b.pendingMonths.length - a.pendingMonths.length);
  }, [membersState, localPayments, viewMonth, viewYear]);

  // Função para lançar pagamento com trava de duplicidade
  const handleLaunchPayment = () => {
    if (!selectedForPayment) return;

    const targetRef = `${paymentForm.month}/${paymentForm.year}`;

    // Zé, aqui a gente trava pra não repetir pagamento do mesmo mês/ano
    const alreadyPaid = selectedForPayment.memberIds.some(mId => 
      localPayments.some(p => p.memberId === mId && p.referenceMonth === targetRef)
    );

    if (alreadyPaid) {
      alert(`Atenção Zé! Este pagamento para ${targetRef} já foi lançado anteriormente. Não podemos repetir!`);
      return;
    }

    const newPays: Payment[] = selectedForPayment.memberIds.map(id => ({
      id: Math.random().toString(36).substr(2, 9),
      memberId: id,
      teamId: teamId,
      amount: paymentForm.amount,
      date: new Date().toISOString().split('T')[0],
      referenceMonth: targetRef,
      status: 'Pago',
      launchedBy: userId
    }));

    setLocalPayments([...localPayments, ...newPays]);
    setShowPayModal(false);
    setPaymentForm({ ...paymentForm, observation: '' });
  };

  if (!team) return <div className="p-10 text-center text-gray-400 font-black">EQUIPE NÃO ENCONTRADA</div>;

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* HEADER DA EQUIPE */}
      <div className="bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
          <div className="flex items-center gap-6">
            <div className="w-16 h-16 bg-blue-600 rounded-3xl flex items-center justify-center text-white shadow-2xl rotate-2">
              <Users className="w-8 h-8" />
            </div>
            <div>
              <h2 className="text-3xl font-black text-gray-900 tracking-tighter leading-none mb-1">{team.name}</h2>
              <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] flex items-center gap-2">
                <MapPin className="w-3.5 h-3.5 text-blue-500" /> {team.city} • MFC {team.state}
              </p>
            </div>
          </div>
          <div className="flex bg-gray-50 p-2 rounded-2xl border border-gray-100 flex-wrap gap-1">
            <button 
              onClick={() => setActiveTab('membros')}
              className={`px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-2 ${activeTab === 'membros' ? 'bg-white shadow-xl text-blue-600 border border-gray-100' : 'text-gray-400'}`}
            >
              <Users className="w-4 h-4" /> Membros
            </button>
            <button 
              onClick={() => setActiveTab('mensalidades')}
              className={`px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-2 ${activeTab === 'mensalidades' ? 'bg-white shadow-xl text-blue-600 border border-gray-100' : 'text-gray-400'}`}
            >
              <DollarSign className="w-4 h-4" /> Mensalidades
            </button>
          </div>
        </div>
      </div>

