      )}

      {activeTab === 'mensalidades' && (
        <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">

          {/* PAINEL DE CONTROLE FINANCEIRO */}
          <div className="flex flex-col lg:flex-row gap-8">
            <div className="lg:w-1/3 space-y-6">
               <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-6">
                  <header>
                      <h3 className="text-xl font-black text-gray-900 tracking-tight">Período de Análise</h3>
                      <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1">Selecione o ano para visualização</p>
                  </header>
                  <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-2">
                          <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Ano</label>
                          <select 
                              className="w-full bg-gray-50 border border-gray-100 rounded-xl px-4 py-3 text-xs font-black text-gray-700 outline-none"
                              value={viewYear}
                              onChange={(e) => setViewYear(parseInt(e.target.value))}
                          >
                              {[2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
                          </select>
                      </div>
                      <div className="space-y-2">
                          <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Mês Base</label>
                          <select 
                              className="w-full bg-gray-50 border border-gray-100 rounded-xl px-4 py-3 text-xs font-black text-gray-700 outline-none"
                              value={viewMonth}
                              onChange={(e) => setViewMonth(parseInt(e.target.value))}
                          >
                              {monthNames.map((n, i) => <option key={i} value={i+1}>{n}</option>)}
                          </select>
                      </div>
                  </div>
                  <div className="p-4 bg-blue-50 rounded-2xl border border-blue-100 flex items-center justify-between">
                      <BarChart3 className="w-5 h-5 text-blue-600" />
                      <div className="text-right">
                          <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest leading-none">Expectativa do Mês</p>
                          <p className="text-lg font-black text-blue-700 leading-tight">R$ {(membersState.length * 50).toFixed(2)}</p>
                      </div>
                  </div>
               </div>

               {/* CARD DE PENDÊNCIA TOTAL */}
               <div className="bg-white p-8 rounded-[2.5rem] border border-red-100 shadow-xl shadow-red-50 relative overflow-hidden group">
                  <AlertTriangle className="absolute -right-4 -bottom-4 w-32 h-32 text-red-500 opacity-5 group-hover:scale-110 transition-transform" />
                  <p className="text-[10px] font-black text-red-400 uppercase tracking-[0.2em] mb-1">Total Pendente no Ano {viewYear}</p>
                  <h3 className="text-4xl font-black text-red-600 tracking-tighter leading-none">R$ {financeStats.pendingAmount.toFixed(2)}</h3>
                  <p className="mt-4 text-[9px] font-bold text-gray-400 italic">Considerando todos os atrasos de jan até {shortMonths[viewMonth-1]}.</p>
